/// The single top-level help text `-h`/`--help` prints regardless of which
/// subcommand it appears on [Repo-grounded — `apps/rhino-cli/src/cli.rs`'s
/// `disable_help_flag = true` plus its manual `cli.help` check: clap's
/// per-subcommand contextual help is disabled in favor of one canonical
/// message everywhere, captured verbatim from
/// `apps/rhino-cli/target/gate/rhino-cli --help`].
module RhinoCli.Cli.HelpText

/// Verbatim, byte-for-byte copy of the Rust binary's `--help` output,
/// including its trailing blank line.
[<Literal>]
let Text =
    "CLI tools for repository management\n\nUsage: rhino-cli [OPTIONS] [COMMAND]\n\nCommands:\n  test-coverage    Test coverage commands (validate)\n  repo-governance  Repository governance audits and validators\n  md               Markdown validators (links, mermaid, heading-hierarchy, naming, frontmatter, etc.)\n  convention       Convention validators (emoji, license)\n  harness          Harness (agent binding) validators and generators\n  governance       Cross-cutting governance gates (word budget, README index/completeness)\n  specs            Spec tree validators and contract codegen helpers\n  repo-config      Repository configuration (`repo-config.yml`) schema-parity validator\n  env              Environment file helpers (init, backup, restore, validate, staged-guard)\n  gate             Gate-registry commands\n  git              Git workflow helpers\n  parity           Rhino CLI byte-identity boundary helpers\n  doctor           Check required tool versions are installed and correct\n  test-contract    Test contract registry and owner fixture commands\n  help             Print this message or the help of the given subcommand(s)\n\nOptions:\n  -v, --verbose          verbose output with timestamps\n  -q, --quiet            quiet mode (errors only)\n  -o, --output <OUTPUT>  output format: text, json, markdown [default: text]\n      --no-color         disable colored output\n      --say <SAY>        echo a message to stdout [default: \"\"]\n  -h, --help             Print help\n  -V, --version          Print version\n\n"

/// Help for the `test-contract` namespace, which `route` prints instead of
/// [`Text`] whenever `-h`/`--help` appears on a `test-contract` invocation.
/// This namespace is F#-only and has no Rust counterpart, so unlike [`Text`]
/// it has no upstream `--help` output to stay byte-identical with; the two
/// snapshot invocation forms and the owner fixture options below are the
/// normative surface.
[<Literal>]
let TestContractText =
    "Test contract registry and owner fixture commands\n\nUsage: rhino-cli test-contract <COMMAND>\n\nCommands:\n  registry snapshot          Project one side of the dual reader into a sorted TSV\n  registry compare           Require byte equality of two identity projections\n  registry validate          Validate the canonical `testing` registry root\n  registry validate-mapping  Validate the frozen and canonical compatibility halves\n  bdd validate               Validate one BDD policy document against the exact-Gherkin rules\n  coverage validate          Validate one coverage policy document, or one real project's native coverage floor\n  layout validate            Validate one native test layout document, or one real project's physical layout\n  manifest validate          Validate one package-manifest disposition document, or one real project's manifest policy\n  validate                   Validate one owner check against an injected fixture\n\nInvocation forms:\n  rhino-cli test-contract registry snapshot --source legacy --output <PATH>\n  rhino-cli test-contract registry snapshot --source canonical --project-list-from <PATH> --output <PATH>\n  rhino-cli test-contract registry compare --legacy <PATH> --canonical <PATH>\n  rhino-cli test-contract registry validate [--require-state <STATE>] [--require-behavior-state <STATE>]\n                                            [--allow-bootstrap <PROJECT>]... [--forbid-legacy] [--forbid-compatibility]\n  rhino-cli test-contract registry validate-mapping --all [--require-state <STATE>] [--require-count <N>]\n  rhino-cli test-contract bdd validate --fixture <NAME>.json\n  rhino-cli test-contract coverage validate --fixture <NAME>.json\n  rhino-cli test-contract coverage validate --project <PROJECT>\n  rhino-cli test-contract layout validate --fixture <NAME>.json\n  rhino-cli test-contract layout validate --project <PROJECT>\n  rhino-cli test-contract manifest validate --fixture <NAME>.json\n  rhino-cli test-contract manifest validate --project <PROJECT>\n  rhino-cli test-contract validate --owner <OWNER_ID> --check <CHECK> --fixture <PATH>\n\nOptions:\n      --source <SOURCE>          which side of the dual reader to project: legacy or canonical\n      --project-list-from <PATH> canonical-source project list; rejected with --source legacy\n      --output <PATH>            destination TSV path\n      --legacy <PATH>            legacy identity projection to compare\n      --canonical <PATH>         canonical identity projection to compare\n      --require-state <STATE>    expanded, migrating, verified, or contracted\n      --require-behavior-state <STATE>\n                                 bootstrap or active\n      --allow-bootstrap <PROJECT>\n                                 admit one project in bootstrap; repeatable\n      --forbid-legacy            fail while the frozen coverage.projects block is still present\n      --forbid-compatibility     fail while the compatibility mappings are still present\n      --all                      validate every compatibility mapping\n      --require-count <N>        require exactly N compatibility mappings\n      --owner <OWNER_ID>         stable owner id, for example O-PUB-RHINO\n      --check <CHECK>            layout, coverage, bdd, or manifest\n      --fixture <PATH>           repository-relative fixture JSON below\n                                 apps/rhino-cli/tests/fixtures/test-contract/owners/<OWNER_ID>/\n      --fixture <NAME>           for the four policy leaves, one document file name, `.json`\n                                 included, below that check's own corpus under\n                                 apps/rhino-cli/src/tests/unit/Fixtures/TestContract/\n      --project <PROJECT>        for coverage/layout/manifest validate, measure the real Nx\n                                 project's project.json and files instead of a fixture document\n  -h, --help                     Print help\n\nExit codes:\n  0  valid\n  1  contract failure\n  2  CLI or input misuse\n"
